analyze.mjs.text:
// The gap this venture exists to check: a top-level `uses:` reference
// pinned to a commit SHA proves nothing about what THAT reference itself
// loads. A reusable workflow or composite action can reference a third
// action by a mutable tag internally, and the caller's own SHA pin never
// sees it — GitHub's own 2026 Actions security roadmap names exactly this
// gap ("a workflow lockfile... like go.sum but for workflows") as unsolved.
//
// This module is the orchestration: for every top-level PINNED remote
// reference, fetch what it points to and classify ITS `uses:` lines the
// same way. `fetchRef` is injected so tests never touch the network — see
// analyze.test.mjs — and the real network call lives only in check.mjs.

import { scanText, classifyUses, parseRemoteRef, PINNED, MUTABLE } from "./classify.mjs";

export const DEFAULT_MAX_FETCHES = 30;

/**
 * @param {string} text - workflow YAML text
 * @param {object} opts
 * @param {string} [opts.filename]
 * @param {(target: {owner:string, repo:string, ref:string, path:string}) => Promise<string|null>} [opts.fetchRef]
 *   Returns the raw file text, or null if it could not be fetched (404, or
 *   any other failure — this function must never throw for a routine
 *   "not found", only for something the caller should treat as an error).
 * @param {number} [opts.maxFetches] - safety cap on network calls per run.
 */
export async function analyzeWorkflow(text, opts = {}) {
  const { filename = "<workflow>", fetchRef = null, maxFetches = DEFAULT_MAX_FETCHES } = opts;

  const findings = scanText(text, filename);
  const nested = [];

  if (!fetchRef) {
    return { file: filename, findings, nested, checkedTransitive: false, transitiveRiskCount: 0, unresolvedCount: 0 };
  }

  let fetchCount = 0;
  for (const f of findings) {
    // Only a pinned top-level reference can hide an unpinned one underneath
    // it undetected — a mutable top-level reference is already a finding
    // the sibling pinned-actions-check reports, and re-flagging it here
    // would just be a second copy of that tool's own result.
    if (f.classification !== PINNED) continue;

    const parsed = parseRemoteRef(f.action);
    if (!parsed) continue;

    if (fetchCount >= maxFetches) {
      nested.push({ parent: f, kind: parsed.kind, status: "skipped-limit" });
      continue;
    }

    let content = null;
    let triedPath = parsed.candidatePaths[0];
    for (const path of parsed.candidatePaths) {
      if (fetchCount >= maxFetches) break;
      fetchCount += 1;
      triedPath = path;
      try {
        // eslint-disable-next-line no-await-in-loop -- each candidate path
        // depends on whether the previous one resolved; there is nothing
        // to parallelize per reference.
        content = await fetchRef({ owner: parsed.owner, repo: parsed.repo, ref: f.ref, path });
      } catch {
        content = null;
      }
      if (content) break;
    }

    if (content == null) {
      // A JS or Docker action legitimately has no action.yml with `uses:`
      // lines, so "not found" here is not itself a finding — but it is
      // never silently read as "checked and clean" either. See summary().
      nested.push({ parent: f, kind: parsed.kind, status: "unresolved", path: triedPath });
      continue;
    }

    const childFindings = scanText(content, `${f.action}@${f.ref} :: ${triedPath}`);
    const transitivelyUnpinned = childFindings.filter((c) => c.classification === MUTABLE);
    nested.push({
      parent: f,
      kind: parsed.kind,
      status: "resolved",
      path: triedPath,
      findings: childFindings,
      transitivelyUnpinned,
    });
  }

  const transitiveRiskCount = nested.reduce((n, entry) => n + (entry.transitivelyUnpinned?.length || 0), 0);
  const unresolvedCount = nested.filter((e) => e.status === "unresolved" || e.status === "skipped-limit").length;

  return { file: filename, findings, nested, checkedTransitive: true, transitiveRiskCount, unresolvedCount };
}

/** Analyze several files (as check.mjs and the browser page both need to)
 * and roll the per-file reports into one summary. */
export async function analyzeWorkflows(files, opts = {}) {
  const reports = [];
  for (const file of files) {
    // eslint-disable-next-line no-await-in-loop -- fetches are already
    // capped per-file by maxFetches; running files concurrently would only
    // make that cap harder to reason about.
    reports.push(await analyzeWorkflow(file.text, { ...opts, filename: file.name }));
  }
  const transitiveRiskCount = reports.reduce((n, r) => n + r.transitiveRiskCount, 0);
  const unresolvedCount = reports.reduce((n, r) => n + r.unresolvedCount, 0);
  const anyTransitiveChecked = reports.some((r) => r.checkedTransitive);
  return { reports, transitiveRiskCount, unresolvedCount, checkedTransitive: anyTransitiveChecked };
}

/** One-line headline, honest about the difference between "clean" and
 * "could not be checked" — a clean scan is not a security claim (see the
 * disclaimer in README.md and index.html). */
export function summaryLine({ transitiveRiskCount, unresolvedCount, checkedTransitive }) {
  if (!checkedTransitive) {
    return "Transitive check not run (no fetch available) — only the top-level `uses:` lines were classified.";
  }
  const parts = [];
  if (transitiveRiskCount > 0) {
    parts.push(`${transitiveRiskCount} reference${transitiveRiskCount === 1 ? "" : "s"} pinned at the top level but loading an unpinned reference underneath`);
  } else {
    parts.push("no pinned reference was found loading an unpinned reference underneath");
  }
  if (unresolvedCount > 0) {
    parts.push(`${unresolvedCount} could not be fetched, so those are unconfirmed, not clean`);
  }
  return parts.join("; ") + ".";
}

check.mjs.text:
#!/usr/bin/env node
// Zero-dependency CLI: scans a repository's .github/workflows for
// third-party references pinned to a commit SHA, then fetches each one's
// own definition (over real, unauthenticated HTTPS to raw.githubusercontent.com
// — public repository content only, no token, no login) to check whether
// IT loads something unpinned underneath. See README.md for what this
// answers and does not answer.
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { analyzeWorkflows } from "./analyze.mjs";

function usage() {
  return `Usage: node check.mjs [dir] [--format text|json] [--fail-on-risk] [--max-fetches N] [--no-network]

  dir              Repository checkout to scan (default: .)
  --format         text (default) or json
  --fail-on-risk   Exit 2 if any pinned reference loads an unpinned one
  --max-fetches    Cap on network requests per run (default: 30)
  --no-network     Classify top-level references only; skip the transitive
                    fetch entirely (offline, like the sibling pinned-actions-check)
`;
}

function parseArgs(argv) {
  const opts = { dir: ".", format: "text", failOnRisk: false, maxFetches: undefined, network: true };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--format") opts.format = argv[++i];
    else if (a === "--fail-on-risk") opts.failOnRisk = true;
    else if (a === "--max-fetches") opts.maxFetches = Number(argv[++i]);
    else if (a === "--no-network") opts.network = false;
    else if (a === "--help" || a === "-h") opts.help = true;
    else if (!a.startsWith("-")) opts.dir = a;
  }
  return opts;
}

function findWorkflowFiles(root) {
  const dir = join(root, ".github", "workflows");
  let entries;
  try {
    entries = readdirSync(dir);
  } catch {
    return [];
  }
  return entries
    .filter((name) => /\.ya?ml$/.test(name))
    .filter((name) => statSync(join(dir, name)).isFile())
    .map((name) => join(dir, name));
}

async function fetchRaw({ owner, repo, ref, path }) {
  const url = `https://raw.githubusercontent.com/${owner}/${repo}/${ref}/${path}`;
  const res = await fetch(url);
  if (!res.ok) return null;
  return await res.text();
}

function printText(result, root) {
  for (const report of result.reports) {
    console.log(`\n${relative(root, report.file) || report.file}`);
    if (!report.findings.length) {
      console.log("  no third-party `uses:` references found");
      continue;
    }
    for (const f of report.findings) {
      console.log(`  L${f.line}  ${f.classification.padEnd(8)} ${f.action}@${f.ref ?? "(none)"}`);
    }
    for (const entry of report.nested) {
      const label = `${entry.parent.action}@${entry.parent.ref}`;
      if (entry.status === "unresolved") {
        console.log(`    -> ${label}: could not fetch ${entry.path} (not found, or not a composite action) — unconfirmed`);
      } else if (entry.status === "skipped-limit") {
        console.log(`    -> ${label}: skipped (--max-fetches reached)`);
      } else if (entry.transitivelyUnpinned.length) {
        for (const child of entry.transitivelyUnpinned) {
          console.log(`    -> ${label} loads ${child.action}@${child.ref} UNPINNED at ${entry.path}:${child.line}`);
        }
      } else {
        console.log(`    -> ${label}: ${entry.path} checked, nothing unpinned underneath`);
      }
    }
  }
  console.log(`\n${result.transitiveRiskCount} transitively-unpinned reference(s), ${result.unresolvedCount} unresolved (unconfirmed).`);
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (opts.help) {
    console.log(usage());
    return 0;
  }

  const files = findWorkflowFiles(opts.dir).map((path) => ({
    name: path,
    text: readFileSync(path, "utf8"),
  }));

  if (!files.length) {
    console.error(`No .github/workflows/*.yml found under ${opts.dir}`);
    return 1;
  }

  const analyzeOpts = { fetchRef: opts.network ? fetchRaw : null };
  if (opts.maxFetches !== undefined) analyzeOpts.maxFetches = opts.maxFetches;

  const result = await analyzeWorkflows(files, analyzeOpts);

  if (opts.format === "json") {
    console.log(JSON.stringify(result, null, 2));
  } else {
    printText(result, opts.dir);
  }

  if (opts.failOnRisk && result.transitiveRiskCount > 0) return 2;
  return 0;
}

main().then((code) => process.exit(code));

classify.mjs.text:
// Classification core, deliberately parallel to the sibling venture
// pinned-actions-check/classify.mjs: same line-by-line regex scan, same
// four classifications, so a reader who knows one tool already knows this
// one's vocabulary. What this module adds is `parseRemoteRef`, which turns
// a pinned remote `uses:` reference into the file path this venture needs
// to fetch to see what THAT reference itself calls.

export const PINNED = "pinned";
export const MUTABLE = "mutable";
export const LOCAL = "local";
export const DOCKER = "docker";

const SHA_RE = /^[0-9a-f]{40}$/i;

// Matches a `uses:` line (top-level "- uses:" or nested "uses:"), capturing
// the action reference. Same shape as pinned-actions-check's _USES_RE.
const USES_RE = /^\s*(?:-\s*)?uses:\s*(\S+)\s*(?:#.*)?$/;

function stripQuotes(value) {
  if (value.length >= 2 && value[0] === value[value.length - 1] && (value[0] === '"' || value[0] === "'")) {
    return value.slice(1, -1);
  }
  return value;
}

/** Classify one `uses:` value. Returns {classification, action, ref}. */
export function classifyUses(rawValue) {
  const value = stripQuotes(rawValue.trim());

  if (value.startsWith("./") || value.startsWith("../")) {
    return { classification: LOCAL, action: value, ref: null };
  }
  if (value.startsWith("docker://")) {
    return { classification: DOCKER, action: value, ref: null };
  }

  const atIndex = value.lastIndexOf("@");
  if (atIndex === -1) {
    return { classification: MUTABLE, action: value, ref: null };
  }

  const action = value.slice(0, atIndex);
  const ref = value.slice(atIndex + 1);
  if (SHA_RE.test(ref)) {
    return { classification: PINNED, action, ref };
  }
  return { classification: MUTABLE, action, ref };
}

/** Scan one file's text for `uses:` lines. Returns findings in the same
 * shape pinned-actions-check emits, so the two tools' JSON never disagrees
 * about what a line means. */
export function scanText(text, filename = "<workflow>") {
  const findings = [];
  const lines = text.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const stripped = line.trim();
    if (stripped.startsWith("#")) continue;
    const match = USES_RE.exec(line);
    if (!match) continue;
    const { classification, action, ref } = classifyUses(match[1]);
    if (classification !== PINNED && classification !== MUTABLE) continue;
    findings.push({ file: filename, line: i + 1, action, ref, classification });
  }
  return findings;
}

/** A pinned remote reference names a repo and, usually, a subpath. This
 * decides what kind of file defines "what that reference itself calls",
 * and where to fetch it from.
 *
 * - `owner/repo/.github/workflows/<file>.yml@<sha>` is a reusable workflow:
 *   the file at that exact path IS the definition, and its own `jobs.*.
 *   steps[].uses` lines are the nested references.
 * - Anything else (`owner/repo@<sha>` or `owner/repo/<subpath>@<sha>`) is an
 *   action. A composite action's nested `uses:` lines live in its
 *   `action.yml` (or `.yaml`) at that subpath — a JS or Docker action has
 *   no such nested `uses:` lines, and fetching finds nothing to flag either
 *   way, which is why both extensions are tried before giving up rather
 *   than guessed from the name.
 *
 * Returns null for a malformed action string (no owner/repo).
 */
export function parseRemoteRef(action) {
  const parts = action.split("/").filter(Boolean);
  if (parts.length < 2) return null;
  const [owner, repo, ...rest] = parts;
  const subpath = rest.join("/");

  if (/^\.github\/workflows\/[^/]+\.ya?ml$/.test(subpath)) {
    return { owner, repo, kind: "reusable-workflow", candidatePaths: [subpath] };
  }

  const base = subpath ? `${subpath}/` : "";
  return { owner, repo, kind: "action", candidatePaths: [`${base}action.yml`, `${base}action.yaml`] };
}

export function classificationCounts(findings) {
  const counts = {};
  for (const finding of findings) {
    counts[finding.classification] = (counts[finding.classification] ?? 0) + 1;
  }
  return counts;
}

